import itertools

def get_permutations(k):
    return list(itertools.permutations(range(k)))

def get_rotations(p):
    k = len(p)
    rotations = []
    for i in range(k):
        rotations.append(p[i:] + p[:i])
    return tuple(sorted(rotations))

def get_orbit(p):
    k = len(p)
    rotations = []
    for i in range(k):
        rotations.append(p[i:] + p[:i])
    return tuple(sorted(rotations))

def solve_small(k):
    from collections import deque

    perms = list(itertools.permutations(range(k)))

    # Orbits
    orbits = []
    visited_perms = set()
    for p in perms:
        if p not in visited_perms:
            # Find all rotations
            rotations = []
            for i in range(k):
                rotations.append(p[i:] + p[:i])
            for r in rotations:
                visited_perms.add(r)
            orbits.append(tuple(sorted(rotations)))

    orbit_to_idx = {}
    for i, orbit in enumerate(orbits):
        for p in orbit:
            orbit_to_idx[p] = i

    num_orbits = len(orbits)
    adj = [set() for _ in range(num_orbits)]

    for p in perms:
        u = orbit_to_idx[p]
        for i in range(k):
            # Swap i and (i+1)%k
            p_list = list(p)
            idx1 = i
            idx2 = (i + 1) % k
            p_list[idx1], p_list[idx2] = p_list[idx2], p_list[idx1]
            v = orbit_to_idx[tuple(p_list)]
            if u != v:
                adj[u].add(v)
                adj[v].add(u)

    # Diameter of the orbit graph
    max_dist = 0
    for i in range(num_orbits):
        # BFS
        dist = [-1] * num_orbits
        dist[i] = 0
        queue = deque([i])
        while queue:
            u = queue.popleft()
            max_dist = max(max_dist, dist[u])
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        # Check if all orbits are reachable
        if any(d == -1 for d in dist):
            return -1 # Should not happen

    return max_dist

for k in range(3, 8):
    print(f"k={k}, diameter={solve_small(k)}")

